import 'dart:ui';
import 'package:flutter/gestures.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

class LearningScreen extends StatefulWidget {
  const LearningScreen({super.key});

  @override
  State<LearningScreen> createState() => _LearningScreenState();
}

class _LearningScreenState extends State<LearningScreen> {
  final PageController _pageController = PageController(keepPage: false);
  final TextEditingController _searchController = TextEditingController();
  int _currentIndex = 0;
  String _topic = '';
  String _query = '';
  bool _changingPage = false;

  @override
  void dispose() {
    _pageController.dispose();
    _searchController.dispose();
    super.dispose();
  }

  List<DevOpsCard> get _visibleCards {
    final query = _query.trim().toLowerCase();
    return learningCards.where((card) {
      if (_topic.isNotEmpty && card.topic != _topic) return false;
      return query.isEmpty ||
          [
            card.topic,
            card.command,
            card.description,
            card.example,
            card.hindiCommand ?? '',
            card.marathiCommand ?? '',
            card.hindiDescription ?? '',
            card.marathiDescription ?? '',
          ].any((text) => text.toLowerCase().contains(query));
    }).toList();
  }

  String _text(String language, String english, String hindi, String marathi) {
    return switch (language) {
      'hi' => hindi,
      'mr' => marathi,
      _ => english,
    };
  }

  void _filter({String? topic, String? query}) {
    if (_pageController.hasClients) _pageController.jumpToPage(0);
    setState(() {
      _topic = topic ?? _topic;
      _query = query ?? _query;
      _currentIndex = 0;
    });
  }

  Future<void> _movePage(int direction) async {
    final target = _currentIndex + direction;
    if (_changingPage ||
        !_pageController.hasClients ||
        target < 0 ||
        target >= _visibleCards.length)
      return;
    _changingPage = true;
    try {
      await _pageController.animateToPage(
        target,
        duration: const Duration(milliseconds: 280),
        curve: Curves.easeInOut,
      );
    } finally {
      _changingPage = false;
    }
  }

  void _handlePointerSignal(PointerSignalEvent event) {
    if (event is PointerScrollEvent && event.scrollDelta.dy != 0) {
      GestureBinding.instance.pointerSignalResolver.register(event, (_) {
        _movePage(event.scrollDelta.dy > 0 ? 1 : -1);
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).colorScheme;
    final language = Localizations.localeOf(context).languageCode;
    final cards = _visibleCards;
    final topics = learningCards.map((card) => card.topic).toSet();
    final allTopics = _text(
      language,
      'All categories',
      'सभी श्रेणियाँ',
      'सर्व श्रेणी',
    );

    return Scaffold(
      appBar: AppBar(
        title: Text(
          _text(language, 'DevOps Learning', 'DevOps सीखें', 'DevOps शिका'),
        ),
        actions: [
          Padding(
            padding: const EdgeInsets.only(right: 16),
            child: Center(
              child: Text(
                '${cards.isEmpty ? 0 : _currentIndex + 1} / ${cards.length}',
                style: const TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
          ),
        ],
      ),
      body: SafeArea(
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 900),
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
                  child: Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: _searchController,
                          onChanged: (query) => _filter(query: query),
                          decoration: InputDecoration(
                            labelText: _text(
                              language,
                              'Search cards',
                              'कार्ड खोजें',
                              'कार्ड शोधा',
                            ),
                            prefixIcon: const Icon(Icons.search_rounded),
                            border: const OutlineInputBorder(),
                            isDense: true,
                            suffixIcon: _query.isEmpty
                                ? null
                                : IconButton(
                                    tooltip: _text(
                                      language,
                                      'Clear search',
                                      'खोज मिटाएँ',
                                      'शोध साफ करा',
                                    ),
                                    icon: const Icon(Icons.close_rounded),
                                    onPressed: () {
                                      _searchController.clear();
                                      _filter(query: '');
                                    },
                                  ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      PopupMenuButton<String>(
                        tooltip: _text(
                          language,
                          'Category',
                          'श्रेणी',
                          'श्रेणी',
                        ),
                        initialValue: _topic,
                        icon: const Icon(Icons.filter_list_rounded),
                        onSelected: (topic) => _filter(topic: topic),
                        itemBuilder: (_) => [
                          PopupMenuItem(value: '', child: Text(allTopics)),
                          for (final topic in topics)
                            PopupMenuItem(value: topic, child: Text(topic)),
                        ],
                      ),
                    ],
                  ),
                ),
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                  child: Align(
                    alignment: Alignment.centerLeft,
                    child: Text(
                      _topic.isEmpty ? allTopics : _topic,
                      style: TextStyle(
                        color: colors.onSurfaceVariant,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                ),
                Expanded(
                  child: cards.isEmpty
                      ? Center(
                          child: Padding(
                            padding: const EdgeInsets.all(16),
                            child: Column(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                const Icon(Icons.search_off_rounded, size: 40),
                                const SizedBox(height: 12),
                                Text(
                                  _text(
                                    language,
                                    'No matching cards',
                                    'कोई कार्ड नहीं मिला',
                                    'कोणतेही कार्ड सापडले नाही',
                                  ),
                                  textAlign: TextAlign.center,
                                ),
                                TextButton.icon(
                                  icon: const Icon(Icons.restart_alt_rounded),
                                  label: Text(
                                    _text(
                                      language,
                                      'Reset filters',
                                      'फ़िल्टर हटाएँ',
                                      'फिल्टर काढा',
                                    ),
                                  ),
                                  onPressed: () {
                                    _searchController.clear();
                                    _filter(topic: '', query: '');
                                  },
                                ),
                              ],
                            ),
                          ),
                        )
                      : ScrollConfiguration(
                          behavior: ScrollConfiguration.of(context).copyWith(
                            dragDevices: {
                              PointerDeviceKind.touch,
                              PointerDeviceKind.mouse,
                              PointerDeviceKind.stylus,
                              PointerDeviceKind.trackpad,
                            },
                          ),
                          child: PageView.builder(
                            controller: _pageController,
                            scrollDirection: Axis.vertical,
                            onPageChanged: (index) =>
                                setState(() => _currentIndex = index),
                            itemCount: cards.length,
                            itemBuilder: (_, index) => Listener(
                              onPointerSignal: _handlePointerSignal,
                              child: _buildCard(
                                cards[index].localized(language),
                                language,
                              ),
                            ),
                          ),
                        ),
                ),
                Padding(
                  padding: const EdgeInsets.fromLTRB(8, 0, 8, 8),
                  child: Row(
                    children: [
                      IconButton(
                        tooltip: _text(language, 'Previous', 'पिछला', 'मागील'),
                        onPressed: cards.isEmpty || _currentIndex == 0
                            ? null
                            : () => _movePage(-1),
                        icon: const Icon(Icons.arrow_upward_rounded),
                      ),
                      Expanded(
                        child: LinearProgressIndicator(
                          value: cards.isEmpty
                              ? 0
                              : (_currentIndex + 1) / cards.length,
                          minHeight: 4,
                          semanticsLabel: _text(
                            language,
                            'Progress',
                            'प्रगति',
                            'प्रगती',
                          ),
                        ),
                      ),
                      IconButton(
                        tooltip: _text(language, 'Next', 'अगला', 'पुढील'),
                        onPressed:
                            cards.isEmpty || _currentIndex == cards.length - 1
                            ? null
                            : () => _movePage(1),
                        icon: const Icon(Icons.arrow_downward_rounded),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildCard(DevOpsCard card, String language) {
    final colors = Theme.of(context).colorScheme;
    return Padding(
      padding: const EdgeInsets.all(16),
      child: Card(
        key: ValueKey(card.id),
        margin: EdgeInsets.zero,
        elevation: 2,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(8),
          side: BorderSide(color: colors.outlineVariant),
        ),
        clipBehavior: Clip.antiAlias,
        child: SingleChildScrollView(
          padding: const EdgeInsets.all(20),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Text(card.icon, style: const TextStyle(fontSize: 28)),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Text(
                      card.topic,
                      style: TextStyle(
                        fontSize: 16,
                        fontWeight: FontWeight.w700,
                        color: colors.primary,
                      ),
                    ),
                  ),
                  Icon(
                    card.isConcept
                        ? Icons.lightbulb_outline_rounded
                        : Icons.terminal_rounded,
                    color: colors.secondary,
                  ),
                ],
              ),
              const SizedBox(height: 24),
              Text(
                card.command,
                style: TextStyle(
                  fontSize: 22,
                  height: 1.4,
                  fontWeight: FontWeight.w700,
                  fontFamily: card.isConcept ? null : 'monospace',
                ),
              ),
              const SizedBox(height: 20),
              Text(
                card.description,
                style: const TextStyle(fontSize: 17, height: 1.6),
              ),
              if (card.example.isNotEmpty) ...[
                const SizedBox(height: 24),
                const Divider(),
                Row(
                  children: [
                    Expanded(
                      child: Text(
                        _text(language, 'Example', 'उदाहरण', 'उदाहरण'),
                        style: TextStyle(color: colors.onSurfaceVariant),
                      ),
                    ),
                    IconButton(
                      tooltip: _text(
                        language,
                        'Copy example',
                        'उदाहरण कॉपी करें',
                        'उदाहरण कॉपी करा',
                      ),
                      icon: const Icon(Icons.copy_rounded, size: 20),
                      onPressed: () async {
                        await Clipboard.setData(
                          ClipboardData(text: card.example),
                        );
                        if (!mounted) return;
                        ScaffoldMessenger.of(context).showSnackBar(
                          SnackBar(
                            content: Text(
                              _text(
                                language,
                                'Example copied',
                                'उदाहरण कॉपी किया गया',
                                'उदाहरण कॉपी केले',
                              ),
                            ),
                          ),
                        );
                      },
                    ),
                  ],
                ),
                Text(
                  card.example,
                  style: TextStyle(
                    fontSize: 15,
                    height: 1.6,
                    fontFamily: 'monospace',
                    color: colors.primary,
                  ),
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }
}

