// ============================================================
// DATA MODEL
// ============================================================

class DevOpsCard {
  final String id;
  final String topic;
  final String icon;
  final String command;
  final String description;
  final String example;
  final String? hindiCommand;
  final String? marathiCommand;
  final String? hindiDescription;
  final String? marathiDescription;
  final bool isConcept;
  final int? sourceQuestion;

  const DevOpsCard({
    this.id = '',
    required this.topic,
    required this.icon,
    required this.command,
    required this.description,
    required this.example,
    this.hindiCommand,
    this.marathiCommand,
    this.hindiDescription,
    this.marathiDescription,
    this.isConcept = false,
    this.sourceQuestion,
  });

  DevOpsCard localized(String language) {
    return DevOpsCard(
      id: id,
      topic: topic,
      icon: icon,
      command: switch (language) {
        'hi' => hindiCommand ?? command,
        'mr' => marathiCommand ?? command,
        _ => command,
      },
      description: switch (language) {
        'hi' => hindiDescription ?? description,
        'mr' => marathiDescription ?? description,
        _ => description,
      },
      example: example,
      isConcept: isConcept,
      sourceQuestion: sourceQuestion,
    );
  }
}
